/**
 * Unicode Confusables Data
 * Generated by scripts/update.ts from unicode.org security data.
 */

import type {
  ConfusablesDataset,
  FlagRangesDataset,
  IntentionalDataset,
  RangesDataset,
} from "../types";
import confusablesData from "./confusables.json";
import defaultIgnorableData from "./default-ignorable.json";
import identifierStatusData from "./identifier-status.json";
import identifierTypeData from "./identifier-type.json";
import intentionalData from "./intentional.json";

/** Full UTS #39 confusables table (prototype mappings). */
export const confusables: ConfusablesDataset = confusablesData as ConfusablesDataset;

/** Intentional pair list (recommended for spoof detection, far fewer false positives). */
export const intentional: IntentionalDataset = intentionalData as IntentionalDataset;

/** UTS #39 Identifier_Status ranges (only "Allowed" entries; unlisted = "Restricted"). */
export const identifierStatus: RangesDataset = identifierStatusData as RangesDataset;

/** UTS #39 Identifier_Type ranges (unlisted = "Not_Character"). */
export const identifierType: RangesDataset = identifierTypeData as RangesDataset;

/** UCD Default_Ignorable_Code_Point ranges, used by the skeleton algorithm. */
export const defaultIgnorable: FlagRangesDataset = defaultIgnorableData as FlagRangesDataset;

const reverseCache = new WeakMap<ConfusablesDataset, Map<string, string[]>>();

/** Lazily built reverse lookup: prototype sequence -> sources that map to it. */
export function getReverseLookup(dataset: ConfusablesDataset): ReadonlyMap<string, string[]> {
  let lookup = reverseCache.get(dataset);
  if (!lookup) {
    lookup = new Map();
    for (const [source, record] of Object.entries(dataset.confusables)) {
      const list = lookup.get(record.target);
      if (list) list.push(source);
      else lookup.set(record.target, [source]);
    }
    reverseCache.set(dataset, lookup);
  }
  return lookup;
}
